<template>
  <div>
    <div v-for="msg in messages" :key="msg.id">{{ msg.content }}</div>
    <input v-model="userInput" @keypress.enter="sendMessage" placeholder="输入问题">
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import axios from 'axios';

const userInput = ref('');
const messages = ref([]);
const userId = ref(localStorage.getItem('userId') || crypto.randomUUID());

onMounted(() => {
  localStorage.setItem('userId', userId.value);
});

const sendMessage = async () => {
  if (!userInput.value) return;
  
  try {
    const response = await axios.post('http://localhost:3000/api/chat', {
      userId: userId.value,
      question: userInput.value
    });
    
    messages.value.push({ role: 'user', content: userInput.value });
    messages.value.push({ role: 'assistant', content: response.data.answer });
    userInput.value = '';
  } catch (error) {
    console.error('请求失败:', error.response?.data?.error || '未知错误');
  }
};
</script>